import {Store} from './state.js';
import {StorageService} from './storage.js';
import {ParcelMap} from './map.js';
import {SyncService} from './sync.js';
import {verifyDeployment, registerAppServiceWorker, markAppReady, requestPersistentStorage, storageHealth, clearAppCaches} from './runtime.js';
import {farmInsights, searchEverything} from './insights.js';
import {computeNotifications, requestNotificationPermission, showBrowserNotification} from './notifications.js';
import {farmReportHtml, parcelReportHtml, clientReportHtml, equipmentReportHtml, openPrintableReport} from './reports.js';
import {buildStatistics} from './statistics.js';
import {askRemoteAssistant} from './remote-ai.js';
import {
  applyImport, createCompleteBackup, exportCsv, exportGeoJson, exportParcelsCsv,
  importPreviewHtml, inspectFiles, makeBackup, mappingOptions, parseCompleteBackup,
  previewNeedsMapping, restoreCompleteBackup, validateBackup, rollbackImportSession
} from './import-export.js';
import {
  APP_VERSION, BUILD_ID, ENTITY_TYPES, campaignFor, download, downloadBlob, escapeHtml, formatEuro,
  formatNumber, geometryAreaHa, geometryCentroid, haversineMeters, isoDate, localDate, localDateTime,
  normalize, pointInGeometry, toNullableNumber, toNumber, uid
} from './utils.js';

const $=selector=>document.querySelector(selector);const $$=selector=>[...document.querySelectorAll(selector)];
let store,parcelMap,sync,currentView='today',workTab='today',parcelFilter='all',selectedParcelId=null,weatherCache=null,lastGps=null,pendingImportFiles=[],fieldModeOpen=false,lastFocused=null,workFilters={parcel:'',type:''},drawingParcelId=null,shortcutPrefix=null;
try{weatherCache=JSON.parse(localStorage.getItem('parcelles:weather')||'null');}catch{weatherCache=null;}
const recentParcelIds=JSON.parse(localStorage.getItem('parcelles:recent')||'[]');

async function init(){
  store=new Store(new StorageService());await store.init();
  sync=new SyncService(store);await sync.init();
  parcelMap=new ParcelMap({onSelect:parcel=>{selectedParcelId=parcel.id;rememberRecent(parcel.id);renderMapSheet();},onToast:toast});
  bindEvents();store.subscribe((data,event)=>renderAfterStoreChange(data,event));
  applyTheme();renderAll();renderNetwork();
  requestPersistentStorage().catch(()=>false);
  registerAppServiceWorker({onUpdate:update=>toast('Une nouvelle version de Parcelles est prête.','success',{label:'Mettre à jour',run:update.activate})}).catch(error=>console.warn('[Parcelles] SW',error));
  window.addEventListener('online',()=>{renderNetwork();if(!weatherCache)refreshWeather({silent:true});});
  window.addEventListener('offline',renderNetwork);
  document.addEventListener('parcelles:gps',event=>{lastGps=event.detail;renderNetwork();if(fieldModeOpen)renderFieldGps(event.detail);});
  window.addEventListener('hashchange',applyHashRoute);
  applyHashRoute();
  if(navigator.onLine)refreshWeather({silent:true});
  setTimeout(maybeSystemNotificationDigest,1600);
  setTimeout(checkStoragePressure,2200);
  setTimeout(maybeOnboarding,120);
  markAppReady();
  setTimeout(async()=>{const check=await verifyDeployment().catch(()=>null);if(check&&!check.ok){console.warn('[Parcelles] ressources manquantes',check.failed);toast(`${check.failed.length} ressource(s) du déploiement sont introuvables. Ouvrez Diagnostic.`,'error');}},800);
}

function state(){return store.snapshot();}
function active(type,data=state()){return(data[type]||[]).filter(item=>!item.deletedAt);}
function parcelById(id,data=state()){return(data.parcelles||[]).find(p=>p.id===id&&!p.deletedAt);}
function workDate(item){return item.plannedDate||item.date;}
function todayIso(){return isoDate(Date.now());}
function setText(selector,text){const el=$(selector);if(el)el.textContent=text;}

function renderCommon(data){setText('#farm-name',data.exploitation.nom||'Mon exploitation');setText('#build-label',`Parcelles · données v${APP_VERSION} · build ${BUILD_ID}`);setText('#today-label',new Intl.DateTimeFormat('fr-FR',{weekday:'long',day:'numeric',month:'long'}).format(new Date()));renderNetwork();applyTheme();}
function renderMapData(data){renderMapSheet(data);if(currentView==='map'){parcelMap.setBaseLayer(data.preferences.mapLayer||'osm');parcelMap.setColorMode(data.preferences.mapColorMode||'culture');parcelMap.render(data);setTimeout(()=>parcelMap.map?.invalidateSize(),20);}}
function renderAfterStoreChange(data,event={}){const entity=event?.entity,kind=event?.kind;if(!entity||entity==='state'||['restore','import','import-rollback'].includes(kind)){renderAll();return;}renderCommon(data);if(entity==='parcelles'){renderToday(data);renderParcels(data);renderWork(data);renderMapData(data);return;}if(entity==='interventions'){renderToday(data);renderWork(data);renderParcels(data);return;}if(entity==='tasks'||entity==='materiels'||entity==='stockItems'||entity==='observations'){renderToday(data);if(entity==='tasks')renderWork(data);return;}if(entity==='points'){renderMapData(data);return;}if(entity==='photos'||entity==='documents'||entity==='rotations'||entity==='grazingSessions'||entity==='clients'||entity==='maintenanceRecords'||entity==='routeSessions'){renderToday(data);return;}}

function renderAll(){
  const data=state();renderCommon(data);renderToday(data);renderParcels(data);renderWork(data);renderMapData(data);
}

function renderNetwork(){
  if(!store)return;const data=state(),pending=data.queue.filter(item=>item.status==='pending').length,offline=!navigator.onLine;
  const button=$('#network-button');if(button)button.classList.toggle('offline',offline);
  setText('#network-label',offline?'Hors connexion':pending?`${pending} à synchroniser`:'À jour');
  const dot=$('#network-dot');if(dot)dot.title=lastGps?`${lastGps.status} · ± ${Math.round(lastGps.accuracy)} m`:offline?'Hors connexion':'En ligne';
}

function toast(message,type='success',action=null){
  const root=$('#toast-root');if(!root)return;const item=document.createElement('div');item.className=`toast ${type==='error'?'error':''}`;
  const span=document.createElement('span');span.textContent=message;item.append(span);
  if(action){const button=document.createElement('button');button.textContent=action.label;button.onclick=async()=>{item.remove();await action.run();};item.append(button);}
  root.append(item);setText('#live-region',message);setTimeout(()=>item.remove(),5200);
}

function switchView(view,{updateHash=true}={}){
  if(!['today','map','parcels','work','more'].includes(view))view='today';currentView=view;
  $$('.view').forEach(el=>el.classList.toggle('is-active',el.id===`view-${view}`));
  $$('.nav-item').forEach(el=>{const on=el.dataset.view===view;el.classList.toggle('is-active',on);if(on)el.setAttribute('aria-current','page');else el.removeAttribute('aria-current');});
  if(updateHash&&location.hash!==`#${view}`)history.replaceState(null,'',`#${view}`);
  if(view==='map'){parcelMap.setBaseLayer(state().preferences.mapLayer||'osm');parcelMap.setColorMode(state().preferences.mapColorMode||'culture');parcelMap.render(state());setTimeout(()=>parcelMap.map?.invalidateSize(),60);}
  $('#main')?.focus({preventScroll:true});
}
function applyHashRoute(){const route=location.hash.replace('#','');if(['map','parcels','work','more','today'].includes(route))switchView(route,{updateHash:false});}

function rememberRecent(id){
  const next=[id,...recentParcelIds.filter(x=>x!==id)].slice(0,6);recentParcelIds.splice(0,recentParcelIds.length,...next);localStorage.setItem('parcelles:recent',JSON.stringify(next));
}

function dataQuality(data){
  const parcels=active('parcelles',data),works=active('interventions',data),photos=active('photos',data),documents=active('documents',data);const issues=[];
  const missingCulture=parcels.filter(p=>!String(p.culture||'').trim());
  const missingSurface=parcels.filter(p=>p.surfaceHa===null||p.surfaceHa===undefined||!Number.isFinite(Number(p.surfaceHa)));
  const missingGeometry=parcels.filter(p=>!p.geometry);
  const noSourceId=parcels.filter(p=>p.source==='import'&&!p.sourceId);
  const seen=new Map(),duplicates=[];for(const p of parcels){const key=normalize(`${p.nom}|${p.commune||''}`);if(seen.has(key))duplicates.push(p,seen.get(key));else seen.set(key,p);}const uniqueDuplicates=[...new Map(duplicates.map(p=>[p.id,p])).values()];
  const ids=new Set(parcels.map(p=>p.id));const orphanWorks=works.filter(w=>!ids.has(w.parcelId));const orphanFiles=[...photos,...documents].filter(f=>f.parcelId&&!ids.has(f.parcelId));
  if(missingCulture.length)issues.push({kind:'parcels',code:'culture',label:`${missingCulture.length} parcelle${missingCulture.length>1?'s':''} sans culture`,ids:missingCulture.map(x=>x.id)});
  if(missingSurface.length)issues.push({kind:'parcels',code:'surface',label:`${missingSurface.length} parcelle${missingSurface.length>1?'s':''} sans surface`,ids:missingSurface.map(x=>x.id)});
  if(missingGeometry.length)issues.push({kind:'parcels',code:'geometry',label:`${missingGeometry.length} parcelle${missingGeometry.length>1?'s':''} sans géométrie`,ids:missingGeometry.map(x=>x.id)});
  if(noSourceId.length)issues.push({kind:'parcels',code:'source',label:`${noSourceId.length} parcelle${noSourceId.length>1?'s':''} importée${noSourceId.length>1?'s':''} sans identifiant source`,ids:noSourceId.map(x=>x.id)});
  if(uniqueDuplicates.length)issues.push({kind:'parcels',code:'duplicate',label:`${uniqueDuplicates.length} parcelle${uniqueDuplicates.length>1?'s':''} dans des doublons potentiels`,ids:uniqueDuplicates.map(x=>x.id)});
  if(orphanWorks.length)issues.push({kind:'interventions',code:'orphan-work',label:`${orphanWorks.length} travail${orphanWorks.length>1?'aux':''} sans parcelle active`,ids:orphanWorks.map(x=>x.id)});
  if(orphanFiles.length)issues.push({kind:'files',code:'orphan-file',label:`${orphanFiles.length} pièce${orphanFiles.length>1?'s':''} jointe${orphanFiles.length>1?'s':''} orpheline${orphanFiles.length>1?'s':''}`,ids:orphanFiles.map(x=>x.id)});
  const fields=Math.max(1,parcels.length*3+works.length);const defects=missingCulture.length+missingSurface.length+missingGeometry.length+orphanWorks.length;return{issues,score:Math.max(0,Math.round((fields-defects)/fields*100))};
}

function renderToday(data){
  const insight=farmInsights(data);
  const parcels=active('parcelles',data),works=active('interventions',data),today=todayIso();const own=parcels.filter(p=>(p.ownershipType||'own')==='own');
  const visibleCards=new Set(data.preferences.homeCards||['weather','today','tasks','alerts','recent']);$$('[data-home-card]').forEach(el=>el.classList.toggle('hidden',!visibleCards.has(el.dataset.homeCard)));
  const totalSurface=own.reduce((sum,p)=>sum+toNumber(p.surfaceHa),0);const todayWorks=works.filter(w=>workDate(w)===today&&w.status!=='Annulé');const pending=works.filter(w=>['À faire','En cours','En retard'].includes(w.status));
  $('#today-summary').innerHTML=[
    [`${formatNumber(totalSurface)} ha`,'Surface exploitation',`${own.length} parcelle${own.length!==1?'s':''}`],
    [String(parcels.length),'Parcelles',`${parcels.filter(p=>p.favorite).length} favorite${parcels.filter(p=>p.favorite).length!==1?'s':''}`],
    [String(todayWorks.length),'Travaux aujourd’hui',todayWorks.length?`${formatNumber(todayWorks.reduce((s,w)=>s+toNumber(w.surfaceWorked),0))} ha concernés`:'Rien de prévu'],
    [String(pending.length),'À suivre',pending.length?'travaux non terminés':'Tout est à jour']
  ].map(([v,l,s])=>`<article class="summary-card"><strong>${escapeHtml(v)}</strong><span>${escapeHtml(l)}</span><small>${escapeHtml(s)}</small></article>`).join('');
  setText('#today-subtitle',todayWorks.length?`${todayWorks.length} travail${todayWorks.length>1?'aux':''} prévu${todayWorks.length>1?'s':''} aujourd’hui.`:'Aucun travail planifié aujourd’hui.');
  const nextWork=[...works].filter(w=>!['Terminé','Annulé'].includes(w.status)&&workDate(w)>=today).sort((a,b)=>String(workDate(a)).localeCompare(String(workDate(b))))[0];const nextTask=active('tasks',data).filter(t=>t.status!=='Terminé'&&t.dueDate&&t.dueDate>=today).sort((a,b)=>String(a.dueDate).localeCompare(String(b.dueDate)))[0];const nextRoot=$('#next-action');if(nextRoot){if(nextWork){const p=parcelById(nextWork.parcelId,data);nextRoot.innerHTML=`<button class="next-action-card" data-action="edit-work" data-id="${nextWork.id}"><span><small>PROCHAINE ACTION</small><strong>${escapeHtml(nextWork.type)}</strong><em>${escapeHtml(p?.nom||'Parcelle')} · ${workDate(nextWork)===today?'Aujourd’hui':localDate(workDate(nextWork))}</em></span><b>›</b></button>`;}else if(nextTask){nextRoot.innerHTML=`<button class="next-action-card" data-action="edit-task" data-id="${nextTask.id}"><span><small>PROCHAINE TÂCHE</small><strong>${escapeHtml(nextTask.title)}</strong><em>${localDate(nextTask.dueDate)}</em></span><b>›</b></button>`;}else nextRoot.innerHTML='';}

  const parcelNames=new Map(parcels.map(p=>[p.id,p.nom]));
  $('#today-work-list').innerHTML=todayWorks.length?todayWorks.slice(0,6).map(w=>workRow(w,parcelNames,{today:true})).join(''):`<div class="empty-state">Rien de prévu aujourd’hui.<br><button class="text-button" data-action="new-work">Planifier un travail</button></div>`;
  const tasks=active('tasks',data).filter(t=>t.status!=='Terminé').sort((a,b)=>String(a.dueDate||'9999').localeCompare(String(b.dueDate||'9999')));const dueTasks=tasks.filter(t=>!t.dueDate||t.dueDate<=today);
  $('#today-task-list').innerHTML=dueTasks.length?dueTasks.slice(0,5).map(t=>`<div class="list-row"><div><strong>${escapeHtml(t.title||'Tâche')}</strong><small>${t.parcelId?`${escapeHtml(parcelNames.get(t.parcelId)||'Parcelle')} · `:''}${t.dueDate?(t.dueDate<today?'En retard':t.dueDate===today?'Aujourd’hui':localDate(t.dueDate)):'Sans échéance'}</small></div><button class="small-button" data-action="finish-task" data-id="${t.id}">Terminer</button></div>`).join(''):'<div class="empty-state">Aucune tâche urgente.<br><button class="text-button" data-action="new-task">Ajouter une tâche</button></div>';
  const alerts=[];const quality=dataQuality(data);quality.issues.slice(0,2).forEach(i=>alerts.push({label:i.label,action:'open-quality'}));
  computeNotifications(data).slice(0,4).forEach(n=>alerts.push({label:`${n.title} · ${n.message}`,action:'open-notifications'}));
  $('#alerts-list').innerHTML=alerts.length?alerts.slice(0,5).map(a=>`<div class="list-row"><div><strong>${escapeHtml(a.label)}</strong><small>À vérifier</small></div><button class="small-button" data-action="${a.action}">Ouvrir</button></div>`).join(''):'<div class="empty-state">Aucune alerte importante.</div>';
  const recent=[...works].sort((a,b)=>new Date(workDate(b))-new Date(workDate(a))).slice(0,5);$('#recent-list').innerHTML=recent.length?recent.map(w=>workRow(w,parcelNames)).join(''):'<div class="empty-state">Aucun travail enregistré.</div>';
  if(weatherCache)renderWeatherCard(weatherCache);else $('#weather-content').innerHTML=data.exploitation.commune||data.exploitation.latitude?'<div class="empty-state">Prévisions non chargées.<br><button class="text-button" data-action="refresh-weather">Actualiser</button></div>':'<div class="empty-state">Ajoutez la localisation de l’exploitation dans les paramètres.</div>';
}
function workRow(item,parcelNames,{today=false}={}){
  const badge=item.status&&item.status!=='Terminé'?`<span class="badge ${item.status==='En retard'?'danger':'info'}">${escapeHtml(item.status)}</span>`:'';
  return`<div class="list-row"><div><strong>${escapeHtml(item.type||'Travail')}</strong><small>${escapeHtml(parcelNames.get(item.parcelId)||'Parcelle supprimée')} · ${today?'Aujourd’hui':localDate(workDate(item))}</small></div><div>${badge}<button class="small-button" data-action="edit-work" data-id="${item.id}">Ouvrir</button></div></div>`;
}

function renderParcels(data){
  const list=filteredParcels(data);const surface=list.reduce((s,p)=>s+toNumber(p.surfaceHa),0);setText('#parcels-counter',`${list.length} parcelle${list.length!==1?'s':''} · ${formatNumber(surface)} ha`);
  const clients=new Map(active('clients',data).map(c=>[c.id,c]));
  $('#parcel-list').innerHTML=list.length?list.map(p=>{
    const badges=[p.favorite?'<span class="badge success">★ Favori</span>':'',normalize(p.status).includes('faire')?'<span class="badge todo">À faire</span>':'',p.ownershipType!=='own'?`<span class="badge info">${p.ownershipType==='client'?'Client':'Prestation'}</span>`:''].filter(Boolean).join('');
    const client=p.clientId?clients.get(p.clientId)?.name:'';
    return`<button class="parcel-card" data-action="open-parcel" data-id="${p.id}"><span class="parcel-card-head"><strong>${escapeHtml(p.nom)}</strong><span>${badges}</span></span><small>${escapeHtml(p.culture||'Culture non renseignée')} · ${formatNumber(p.surfaceHa)} ha${p.commune?` · ${escapeHtml(p.commune)}`:''}${client?` · ${escapeHtml(client)}`:''}</small></button>`;
  }).join(''):'<div class="empty-state">Aucune parcelle ne correspond aux filtres.</div>';
  const recent=recentParcelIds.map(id=>parcelById(id,data)).filter(Boolean);$('#recent-parcels').innerHTML=recent.length?`<span class="form-note">Récentes</span>${recent.map(p=>`<button class="recent-chip" data-action="open-parcel" data-id="${p.id}">${escapeHtml(p.nom)}</button>`).join('')}`:'';
}
function filteredParcels(data=state()){
  const query=$('#parcel-search')?.value.trim()||'';let list=active('parcelles',data);const clients=new Map(active('clients',data).map(c=>[c.id,c.name]));
  if(parcelFilter==='archived')list=list.filter(p=>p.archived);else list=list.filter(p=>!p.archived);if(parcelFilter==='todo')list=list.filter(p=>normalize(p.status).includes('faire'));if(parcelFilter==='favorites')list=list.filter(p=>p.favorite);if(parcelFilter==='clients')list=list.filter(p=>p.ownershipType&&p.ownershipType!=='own');
  let minSurface=null,maxSurface=null;const gt=query.match(/>\s*([\d.,]+)/),lt=query.match(/<\s*([\d.,]+)/);if(gt)minSurface=toNumber(gt[1]);if(lt)maxSurface=toNumber(lt[1]);
  const tokens=normalize(query.replace(/[<>]\s*[\d.,]+\s*(ha)?/gi,'')).split(/\s+/).filter(Boolean);
  list=list.filter(p=>{if(minSurface!==null&&toNumber(p.surfaceHa)<=minSurface)return false;if(maxSurface!==null&&toNumber(p.surfaceHa)>=maxSurface)return false;const hay=normalize([p.nom,p.culture,p.commune,p.ilot,p.sourceId,p.exploitant,clients.get(p.clientId)].join(' '));return tokens.every(t=>hay.includes(t));});
  const sort=$('#parcel-sort')?.value||'name';const works=active('interventions',data);const lastDate=id=>Math.max(0,...works.filter(w=>w.parcelId===id).map(w=>new Date(workDate(w)).getTime()||0));
  list.sort((a,b)=>sort==='surface-desc'?toNumber(b.surfaceHa)-toNumber(a.surfaceHa):sort==='surface-asc'?toNumber(a.surfaceHa)-toNumber(b.surfaceHa):sort==='culture'?String(a.culture||'').localeCompare(String(b.culture||''),'fr'):sort==='commune'?String(a.commune||'').localeCompare(String(b.commune||''),'fr'):sort==='recent'?lastDate(b.id)-lastDate(a.id):String(a.nom).localeCompare(String(b.nom),'fr'));
  return list;
}

function renderWork(data){
  const works=filteredWorks(data),parcels=new Map(active('parcelles',data).map(p=>[p.id,p]));
  $('#work-list').innerHTML=works.length?works.map(w=>{
    const p=parcels.get(w.parcelId);return`<article class="work-card"><div class="work-card-head"><div><strong>${escapeHtml(w.type)}</strong><small>${escapeHtml(p?.nom||'Parcelle supprimée')} · ${localDate(workDate(w))}</small></div><span class="badge ${w.status==='En retard'?'danger':w.status==='Terminé'?'success':'info'}">${escapeHtml(w.status||'Terminé')}</span></div><div class="work-meta">${w.product?`<span class="badge">${escapeHtml(w.product)}</span>`:''}${w.surfaceWorked?`<span class="badge">${formatNumber(w.surfaceWorked)} ha</span>`:''}${w.cost?`<span class="badge">${formatEuro(w.cost)}</span>`:''}</div><div><button class="small-button" data-action="edit-work" data-id="${w.id}">Modifier</button> ${w.status!=='Terminé'?`<button class="small-button" data-action="finish-work" data-id="${w.id}">Terminer</button>`:''} <button class="small-button" data-action="duplicate-work" data-id="${w.id}">Refaire</button></div></article>`;
  }).join(''):'<div class="empty-state">Aucun travail dans cette vue.</div>';
}
function filteredWorks(data=state()){
  const works=active('interventions',data),today=todayIso(),query=normalize($('#work-search')?.value||'');let list=works;
  if(workTab==='today')list=list.filter(w=>workDate(w)===today&&w.status!=='Annulé');
  if(workTab==='upcoming')list=list.filter(w=>workDate(w)>today&&!['Terminé','Annulé'].includes(w.status));
  if(workTab==='history')list=list.filter(w=>w.status==='Terminé'||workDate(w)<today);
  const parcels=new Map(active('parcelles',data).map(p=>[p.id,p.nom]));if(query)list=list.filter(w=>normalize([w.type,w.product,w.operator,w.note,parcels.get(w.parcelId)].join(' ')).includes(query));
  if(workFilters.parcel)list=list.filter(w=>w.parcelId===workFilters.parcel);
  if(workFilters.type)list=list.filter(w=>normalize(w.type)===normalize(workFilters.type));
  const chips=[];if(workFilters.parcel)chips.push(`<button class="filter-chip is-active" data-action="clear-work-filter" data-filter="parcel">${escapeHtml(parcels.get(workFilters.parcel)||'Parcelle')} ×</button>`);if(workFilters.type)chips.push(`<button class="filter-chip is-active" data-action="clear-work-filter" data-filter="type">${escapeHtml(workFilters.type)} ×</button>`);if(chips.length)chips.push('<button class="text-button" data-action="clear-work-filters">Effacer</button>');const summary=$('#work-filter-summary');if(summary)summary.innerHTML=chips.join('');
  return[...list].sort((a,b)=>workTab==='history'?new Date(workDate(b))-new Date(workDate(a)):new Date(workDate(a))-new Date(workDate(b)));
}

function renderMapSheet(data=state()){
  const root=$('#map-parcel-sheet');if(!root)return;const p=parcelById(selectedParcelId,data);if(!p){root.innerHTML='<div class="sheet-empty">Touchez une parcelle pour afficher ses informations.</div>';return;}
  const next=active('interventions',data).filter(w=>w.parcelId===p.id&&!['Terminé','Annulé'].includes(w.status)).sort((a,b)=>new Date(workDate(a))-new Date(workDate(b)))[0];
  root.innerHTML=`<div class="map-sheet-head"><div><h2>${escapeHtml(p.nom)}</h2><p>${escapeHtml(p.culture||'Culture non renseignée')} · ${formatNumber(p.surfaceHa)} ha${p.commune?` · ${escapeHtml(p.commune)}`:''}</p></div>${p.favorite?'<span class="badge success">★</span>':''}</div>${next?`<p class="form-note">Prochain : ${escapeHtml(next.type)} · ${localDate(workDate(next))}</p>`:''}<div class="map-sheet-actions"><button class="button primary" data-action="open-parcel" data-id="${p.id}">Ouvrir</button><button class="button secondary" data-action="route-parcel" data-id="${p.id}">Itinéraire</button><button class="button secondary" data-action="new-work" data-parcel-id="${p.id}">＋ Travail</button></div>`;
}


function weatherWarnings(data=weatherCache){if(!data?.daily)return[];const p=state().preferences,out=[];const wind=Number(p.weatherWindThreshold||0),rain=Number(p.weatherRainThreshold||0);(data.daily.time||[]).forEach((day,i)=>{const w=Number(data.daily.wind_gusts_10m_max?.[i]??data.daily.wind_speed_10m_max?.[i]??0),r=Number(data.daily.precipitation_sum?.[i]??0);if(wind&&w>=wind)out.push({day,type:'Vent',value:`${Math.round(w)} km/h`});if(rain&&r>=rain)out.push({day,type:'Pluie',value:`${formatNumber(r)} mm`});});return out;}
async function openParcelWeather(id){const p=parcelById(id),c=geometryCentroid(p?.geometry);if(!p||!c)return toast('Cette parcelle n’a pas de position exploitable.','error');if(!navigator.onLine)return toast('La météo de parcelle demande une connexion réseau.','error');modal('Météo de la parcelle',p.nom,'<div class="empty-state">Chargement…</div>','','small');try{const url=`https://api.open-meteo.com/v1/forecast?latitude=${c.latitude}&longitude=${c.longitude}&current=temperature_2m,relative_humidity_2m,precipitation,wind_speed_10m,wind_gusts_10m&daily=temperature_2m_max,temperature_2m_min,precipitation_sum,precipitation_probability_max,wind_speed_10m_max,wind_gusts_10m_max&timezone=auto&forecast_days=${state().preferences.weatherDays===14?14:7}`;const r=await fetch(url);if(!r.ok)throw new Error(`service météo ${r.status}`);const w=await r.json();modal('Météo de la parcelle',p.nom,`<div class="weather-main"><div class="weather-temp">${Math.round(w.current.temperature_2m)}°</div><div><strong>${escapeHtml(p.nom)}</strong><br><small>Humidité ${Math.round(w.current.relative_humidity_2m||0)} % · vent ${Math.round(w.current.wind_speed_10m||0)} km/h</small></div></div><div class="table-wrap"><table><thead><tr><th>Jour</th><th>Temp.</th><th>Pluie</th><th>Rafales</th></tr></thead><tbody>${w.daily.time.map((d,i)=>`<tr><td>${localDate(d)}</td><td>${Math.round(w.daily.temperature_2m_min[i])}° / ${Math.round(w.daily.temperature_2m_max[i])}°</td><td>${formatNumber(w.daily.precipitation_sum[i]||0)} mm · ${Math.round(w.daily.precipitation_probability_max[i]||0)} %</td><td>${Math.round(w.daily.wind_gusts_10m_max[i]||0)} km/h</td></tr>`).join('')}</tbody></table></div>`,`<button class="button primary" data-action="close-modal">Fermer</button>`,'large');}catch(error){closeModal();toast(`Météo indisponible : ${error.message}`,'error');}}
function renderWeatherCard(data){
  if(!data?.current)return;const rainNow=data.current.precipitation??0;const age=data.loadedAt?Math.max(0,Math.round((Date.now()-data.loadedAt)/60000)):null;const warnings=weatherWarnings(data);$('#weather-content').innerHTML=`<div class="weather-main"><div class="weather-temp">${Math.round(data.current.temperature_2m)}°</div><div><strong>${escapeHtml(data.place)}</strong><br><small>Vent ${Math.round(data.current.wind_speed_10m||0)} km/h · humidité ${Math.round(data.current.relative_humidity_2m||0)} % · pluie ${rainNow} mm${age!==null?` · actualisé il y a ${age} min`:''}</small></div></div>${warnings.length?`<div class="notice warning" style="margin:10px 0">${warnings.slice(0,2).map(w=>`${escapeHtml(w.type)} ${escapeHtml(localDate(w.day))} : ${escapeHtml(w.value)}`).join('<br>')}</div>`:''}<div class="weather-days">${data.daily.time.slice(0,4).map((day,i)=>`<div class="weather-day"><strong>${new Intl.DateTimeFormat('fr-FR',{weekday:'short'}).format(new Date(day))}</strong><br>${Math.round(data.daily.temperature_2m_max[i])}° / ${Math.round(data.daily.temperature_2m_min[i])}°<br><small>${Math.round(data.daily.precipitation_probability_max[i]||0)} % pluie</small></div>`).join('')}</div>`;
}
async function refreshWeather({silent=false}={}){
  const farm=state().exploitation;try{
    if(!silent)toast('Actualisation de la météo…');let lat=toNullableNumber(farm.latitude),lon=toNullableNumber(farm.longitude),place=farm.commune||farm.nom;
    if(lat===null||lon===null){if(!farm.commune)throw new Error('Renseignez la commune ou les coordonnées de l’exploitation.');const r=await fetch(`https://geocoding-api.open-meteo.com/v1/search?name=${encodeURIComponent(farm.commune)}&count=1&language=fr&format=json`);if(!r.ok)throw new Error('Géocodage indisponible.');const hit=(await r.json()).results?.[0];if(!hit)throw new Error('Commune introuvable.');lat=hit.latitude;lon=hit.longitude;place=hit.name;}
    const url=`https://api.open-meteo.com/v1/forecast?latitude=${lat}&longitude=${lon}&current=temperature_2m,relative_humidity_2m,precipitation,weather_code,wind_speed_10m,wind_gusts_10m&hourly=temperature_2m,relative_humidity_2m,precipitation_probability,precipitation,wind_speed_10m,wind_gusts_10m&daily=weather_code,temperature_2m_max,temperature_2m_min,precipitation_sum,precipitation_probability_max,wind_speed_10m_max,wind_gusts_10m_max&timezone=auto&forecast_days=${state().preferences.weatherDays===14?14:7}`;
    const response=await fetch(url);if(!response.ok)throw new Error(`service météo ${response.status}`);weatherCache={...(await response.json()),place,latitude:lat,longitude:lon,loadedAt:Date.now()};localStorage.setItem('parcelles:weather',JSON.stringify(weatherCache));renderToday(state());if(!silent)toast('Météo actualisée.');
  }catch(error){const cached=JSON.parse(localStorage.getItem('parcelles:weather')||'null');if(cached){weatherCache=cached;renderToday(state());if(!silent)toast('Météo réseau indisponible : prévisions en cache affichées.','error');}else if(!silent)toast(`Météo indisponible : ${error.message}`,'error');}
}

