function closeModal(){const root=$('#modal-root');root.classList.remove('has-modal');root.innerHTML='';lastFocused?.focus?.();}

function openParcel(id){const p=parcelById(id);if(!p)return;selectedParcelId=id;rememberRecent(id);openParcelDetail(id);}
function openParcelDetail(id,tab='summary'){
  const data=state(),p=parcelById(id,data);if(!p)return;const works=active('interventions',data).filter(w=>w.parcelId===id).sort((a,b)=>new Date(workDate(b))-new Date(workDate(a)));const photos=active('photos',data).filter(x=>x.parcelId===id);const docs=active('documents',data).filter(x=>x.parcelId===id);
  const tabs=[['summary','Résumé'],['work','Travaux'],['economy','Économie'],['photos','Photos'],['more','Plus']];
  let body='';
  if(tab==='summary')body=parcelSummaryHtml(p,works,data);
  if(tab==='work')body=works.length?`<div class="stack-list">${works.map(w=>workRow(w,new Map([[id,p.nom]]))).join('')}</div>`:'<div class="empty-state">Aucun travail enregistré.</div>';
  if(tab==='economy')body=parcelEconomyHtml(p,works);
  if(tab==='photos')body=`<div id="parcel-photo-gallery" class="photo-grid"><div class="empty-state">Chargement…</div></div><div style="margin-top:12px"><button class="button secondary" data-action="add-photo" data-id="${id}">📷 Ajouter une photo</button> <button class="button secondary" data-action="attach-file" data-id="${id}">Ajouter un document</button></div>${docs.length?`<h3>Documents</h3><div class="stack-list">${docs.map(d=>`<div class="list-row"><div><strong>${escapeHtml(d.name)}</strong><small>${localDate(d.createdAt)}</small></div><button class="small-button" data-action="view-attachment" data-type="documents" data-id="${d.id}">Ouvrir</button></div>`).join('')}</div>`:''}`;
  if(tab==='more')body=`<div class="stack-list"><div class="list-row"><div><strong>Note permanente</strong><small>${escapeHtml(p.notes||'Aucune note')}</small></div><button class="small-button" data-action="add-note" data-id="${id}">Modifier</button></div><div class="list-row"><div><strong>Source</strong><small>${escapeHtml(p.source||'local')} · ${escapeHtml(p.sourceId||'sans identifiant')}</small></div></div><div class="list-row"><div><strong>Îlot / exploitant</strong><small>${escapeHtml(p.ilot||'—')} · ${escapeHtml(p.exploitant||'—')}</small></div></div></div>`;
  modal(p.nom,`${p.culture||'Culture non renseignée'} · ${formatNumber(p.surfaceHa)} ha`,`${parcelHeaderActions(p)}<div class="segmented" style="grid-template-columns:repeat(5,1fr);width:100%">${tabs.map(([key,label])=>`<button class="${tab===key?'is-active':''}" data-action="parcel-tab" data-id="${id}" data-tab="${key}">${label}</button>`).join('')}</div><div style="margin-top:16px">${body}</div>`,`<button class="button secondary" data-action="close-modal">Fermer</button>`,'large');
  if(tab==='photos')renderPhotoGallery(id,photos);
}
function parcelHeaderActions(p){return`<div class="map-sheet-actions" style="margin:0 0 16px"><button class="button primary" data-action="new-work" data-parcel-id="${p.id}">＋ Travail</button><button class="button secondary" data-action="route-parcel" data-id="${p.id}">Itinéraire</button><button class="button secondary" data-action="toggle-favorite" data-id="${p.id}">${p.favorite?'★ Favori':'☆ Favori'}</button><button class="button secondary" data-action="parcel-actions" data-id="${p.id}">•••</button></div>`;}
function parcelSummaryHtml(p,works,data){
  const next=works.filter(w=>!['Terminé','Annulé'].includes(w.status)).sort((a,b)=>new Date(workDate(a))-new Date(workDate(b)))[0],last=works.find(w=>w.status==='Terminé')||works[0];const client=active('clients',data).find(c=>c.id===p.clientId);
  return`<dl class="definition-list"><div><dt>Culture</dt><dd>${escapeHtml(p.culture||'—')}</dd></div><div><dt>Surface</dt><dd>${formatNumber(p.surfaceHa)} ha</dd></div><div><dt>Commune</dt><dd>${escapeHtml(p.commune||'—')}</dd></div><div><dt>Îlot</dt><dd>${escapeHtml(p.ilot||'—')}</dd></div><div><dt>Type</dt><dd>${p.ownershipType==='own'?'Mon exploitation':p.ownershipType==='client'?`Client${client?` · ${escapeHtml(client.name)}`:''}`:'Prestation'}</dd></div><div><dt>Prochain travail</dt><dd>${next?`${escapeHtml(next.type)} · ${localDate(workDate(next))}`:'—'}</dd></div><div><dt>Dernier travail</dt><dd>${last?`${escapeHtml(last.type)} · ${localDate(workDate(last))}`:'—'}</dd></div><div><dt>Note</dt><dd>${escapeHtml(p.notes||'—')}</dd></div></dl>`;
}
function parcelEconomyHtml(p,works){
  const econ=p.economics||{},surface=toNumber(p.surfaceHa),yieldValue=toNumber(econ.yield),price=toNumber(econ.salePrice),productHa=yieldValue&&price?yieldValue*price:toNumber(econ.productHa),productTotal=productHa*surface;
  const comp={machine:works.reduce((s,w)=>s+toNumber(w.machineCost),0),fuel:works.reduce((s,w)=>s+toNumber(w.fuelCost),0),inputs:works.reduce((s,w)=>s+toNumber(w.inputCost),0),operator:works.reduce((s,w)=>s+toNumber(w.operatorCost),0),other:works.reduce((s,w)=>s+toNumber(w.otherCost),0)};const worksTotal=works.reduce((s,w)=>s+toNumber(w.cost),0),known=Object.values(comp).reduce((a,b)=>a+b,0),unallocated=Math.max(0,worksTotal-known);const manualHa=toNumber(econ.inputCostHa)+toNumber(econ.operatorCostHa)+toNumber(econ.otherCostHa),manualTotal=manualHa*surface,totalCosts=worksTotal+manualTotal,costHa=surface?totalCosts/surface:0,marginTotal=productTotal-totalCosts,marginHa=surface?marginTotal/surface:0;
  return`<div class="economy-kpis"><div><small>Produit brut</small><strong>${productHa?formatEuro(productHa):'—'} /ha</strong><em>${productHa?formatEuro(productTotal):'—'} total</em></div><div><small>Charges</small><strong>${formatEuro(costHa)} /ha</strong><em>${formatEuro(totalCosts)} total</em></div><div class="${marginTotal<0?'negative':''}"><small>Marge brute</small><strong>${productHa?formatEuro(marginHa):'—'} /ha</strong><em>${productHa?formatEuro(marginTotal):'—'} total</em></div></div><h3>Détail des coûts saisis</h3><dl class="definition-list"><div><dt>Machine</dt><dd>${formatEuro(comp.machine)}</dd></div><div><dt>Carburant</dt><dd>${formatEuro(comp.fuel)}</dd></div><div><dt>Intrants travaux</dt><dd>${formatEuro(comp.inputs)}</dd></div><div><dt>Opérateur</dt><dd>${formatEuro(comp.operator)}</dd></div><div><dt>Autres travaux</dt><dd>${formatEuro(comp.other)}</dd></div>${unallocated?`<div><dt>Coûts non ventilés</dt><dd>${formatEuro(unallocated)}</dd></div>`:''}<div><dt>Charges complémentaires / ha</dt><dd>${formatEuro(manualHa)}</dd></div></dl><p class="form-note">Estimation de pilotage fondée sur les données saisies dans Parcelles ; elle ne remplace pas la comptabilité.</p>`;
}

async function renderPhotoGallery(parcelId,photos){
  const root=$('#parcel-photo-gallery');if(!root)return;if(!photos.length){root.innerHTML='<div class="empty-state">Aucune photo.</div>';return;}const urls=[];
  for(const photo of photos){const blob=await store.storage.blobGet(photo.id);if(blob){const url=URL.createObjectURL(blob);urls.push(url);const button=document.createElement('button');button.className='photo-thumb';button.dataset.action='view-attachment';button.dataset.type='photos';button.dataset.id=photo.id;button.innerHTML=`<img src="${url}" alt="${escapeHtml(photo.note||photo.name||'Photo de parcelle')}">`;root.append(button);}}
  root.querySelector('.empty-state')?.remove();setTimeout(()=>urls.forEach(url=>URL.revokeObjectURL(url)),60000);
}

