  modal(work&&!duplicate?'Modifier le travail':duplicate?'Refaire ce travail':'Nouveau travail','Un cas simple peut être enregistré avec les champs essentiels uniquement.',`${datalists}<form id="work-form"><div class="form-grid"><label>Parcelle *<select name="parcelId" required>${parcels.map(p=>`<option value="${p.id}" ${item.parcelId===p.id?'selected':''}>${escapeHtml(p.nom)}</option>`).join('')}</select></label><label>Modèle<select id="work-template"><option value="">Aucun modèle</option>${templates.map(t=>`<option value="${t.id}">${escapeHtml(t.name)}</option>`).join('')}</select></label><label>Type *<input name="type" list="recent-work-types" required value="${escapeHtml(item.type)}" placeholder="Fauche, semis…"></label><label>Date<input name="date" type="date" required value="${isoDate(item.date)}"></label><label>Statut<select name="status">${['À faire','En cours','Terminé','En retard','Annulé'].map(v=>`<option ${item.status===v?'selected':''}>${v}</option>`).join('')}</select></label><label>Surface travaillée (ha)<input name="surfaceWorked" inputmode="decimal" type="number" min="0" step="0.01" value="${item.surfaceWorked??''}"></label></div>
  <details class="form-section"><summary>Plus de détails</summary><div class="form-grid"><label>Heure début<input name="startTime" type="time" value="${escapeHtml(item.startTime)}"></label><label>Heure fin<input name="endTime" type="time" value="${escapeHtml(item.endTime)}"></label><label>Produit<input name="product" list="recent-products" value="${escapeHtml(item.product)}"></label><label>Dose<input name="dose" inputmode="decimal" value="${escapeHtml(item.dose)}"></label><label>Unité dose<select name="doseUnit"><option value="">—</option>${['kg/ha','L/ha','t/ha','m³/ha','unité/ha','q/ha','mm','autre'].map(v=>`<option ${item.doseUnit===v?'selected':''}>${v}</option>`).join('')}</select></label><label>Prix produit / unité (€)<input name="productUnitPrice" inputmode="decimal" value="${item.productUnitPrice??''}"></label><label>Durée (h)<input name="duration" type="number" min="0" step="0.1" value="${item.duration??''}"></label><label>Carburant (L)<input name="fuel" type="number" min="0" step="0.1" value="${item.fuel??''}"></label><label>Opérateur<input name="operator" list="recent-operators" value="${escapeHtml(item.operator)}"></label><label>Matériel<select name="equipmentId"><option value="">Non renseigné</option>${machines.map(m=>`<option value="${m.id}" ${item.equipmentId===m.id?'selected':''}>${escapeHtml(m.nom)}</option>`).join('')}</select></label><label>Coût machine (€)<input name="machineCost" inputmode="decimal" value="${item.machineCost??''}" placeholder="auto si vide"></label><label>Coût carburant (€)<input name="fuelCost" inputmode="decimal" value="${item.fuelCost??''}" placeholder="auto si vide"></label><label>Coût intrants (€)<input name="inputCost" inputmode="decimal" value="${item.inputCost??''}"></label><label>Coût opérateur (€)<input name="operatorCost" inputmode="decimal" value="${item.operatorCost??''}"></label><label>Autres coûts (€)<input name="otherCost" inputmode="decimal" value="${item.otherCost??''}"></label><label>Coût total (€)<input name="cost" inputmode="decimal" value="${item.cost??''}" placeholder="somme automatique si vide"></label><label class="span-2">Note<textarea name="note">${escapeHtml(item.note)}</textarea></label><label><input type="checkbox" name="saveTemplate"> Enregistrer comme modèle</label><label><input type="checkbox" name="weatherSnapshot" ${item.weatherSnapshot?'checked':''}> Conserver la météo actuelle</label><label><input type="checkbox" name="addPhotoAfter"> Ajouter une photo après</label></div></details></form>`,`<button class="button secondary" data-action="close-modal">Annuler</button>${work&&!duplicate?'<button class="button secondary" id="attach-work">Pièce jointe</button><button class="button secondary" id="delete-work">Supprimer</button>':''}<button class="button primary" id="save-work">Enregistrer</button>`,'large');
  const form=$('#work-form');
  $('#work-template').onchange=()=>{const t=templates.find(x=>x.id===$('#work-template').value);if(!t)return;for(const key of ['type','product','dose','doseUnit','operator','equipmentId'])if(t[key]!==undefined&&form.elements[key])form.elements[key].value=t[key];};
