  $('#save-work').onclick=async()=>{if(!form.reportValidity())return;recalcDuration();const v=Object.fromEntries(new FormData(form));const machine=machines.find(m=>m.id===v.equipmentId),duration=toNullableNumber(v.duration),fuel=toNullableNumber(v.fuel);const machineCost=String(v.machineCost).trim()?toNumber(v.machineCost):(machine&&duration!==null?duration*toNumber(machine.hourlyCost):0);const fuelCost=String(v.fuelCost).trim()?toNumber(v.fuelCost):(fuel!==null?fuel*toNumber(data.preferences.fuelPrice):0);const inputCost=String(v.inputCost).trim()?toNumber(v.inputCost):(toNullableNumber(v.dose)!==null&&toNullableNumber(v.productUnitPrice)!==null&&toNullableNumber(v.surfaceWorked)!==null?toNumber(v.dose)*toNumber(v.productUnitPrice)*toNumber(v.surfaceWorked):0);const operatorCost=toNumber(v.operatorCost),otherCost=toNumber(v.otherCost),components=machineCost+fuelCost+inputCost+operatorCost+otherCost,total=String(v.cost).trim()?toNumber(v.cost):components;const weatherSnapshot=form.elements.weatherSnapshot.checked&&weatherCache?{capturedAt:Date.now(),place:weatherCache.place,temperature:weatherCache.current?.temperature_2m,precipitation:weatherCache.current?.precipitation,wind:weatherCache.current?.wind_speed_10m,gust:weatherCache.current?.wind_gusts_10m}:item.weatherSnapshot;const entity={...item,...v,id:item.id,cost:total,surfaceWorked:toNullableNumber(v.surfaceWorked),dose:toNullableNumber(v.dose)??v.dose,productUnitPrice:toNullableNumber(v.productUnitPrice),duration,fuel,machineCost,fuelCost,inputCost,operatorCost,otherCost,weatherSnapshot,campaignId:campaignFor(v.date),source:item.id?'local':(source.source||'local')};const saved=await store.upsert('interventions',entity,{label:`Travail ${item.id?'modifié':'enregistré'} : ${v.type}`});if(form.elements.saveTemplate.checked){await store.upsert('templates',{name:`${v.type}${v.product?` · ${v.product}`:''}`,type:v.type,product:v.product,dose:v.dose,doseUnit:v.doseUnit,operator:v.operator,equipmentId:v.equipmentId},{label:`Modèle créé : ${v.type}`,queue:false});}const addPhoto=form.elements.addPhotoAfter.checked;closeModal();if(addPhoto){openAttachmentForm(saved.parcelId,{photoOnly:true,interventionId:saved.id});return;}toast('Travail enregistré.','success',{label:'Ouvrir',run:()=>openWorkForm(saved)});};
